protected int tryLiquidFuel(IFluidHandler handler, boolean consume) {
  FluidStack fluid = handler.getFluidInTank(0);
  MeltingFuel recipe = findRecipe(fluid.getFluid());
  if (recipe != null) {
    int amount = recipe.getAmount(fluid.getFluid());
    if (fluid.getAmount() >= amount) {
      if (consume) {
        FluidStack drained = handler.drain(new FluidStack(fluid, amount), FluidAction.EXECUTE);
        if (drained.getAmount() != amount) {
          TConstruct.LOG.error("Invalid amount of fuel drained from tank");
        }
        fuel += recipe.getDuration();
        fuelQuality = recipe.getDuration();
        temperature = recipe.getTemperature();
        rate = recipe.getRate();
        parent.setChangedFast();
        return temperature;
      } else {
        return recipe.getTemperature();
      }
    }
  }
  return 0;
}

@Override
public int findFuel(boolean consume) {
  // only fetch a handler if we haven't done so
  if (fluidHandler != null) {
    // if we have a handler, try to use that if possible
    if (fluidHandler.isPresent()) {
      int temperature = tryLiquidFuel(fluidHandler.orElse(EmptyFluidHandler.INSTANCE), consume);
      if (temperature > 0) {
        return temperature;
      }
    }
  } else if (lastPos != NULL_POS) {
    // if no handler, try to find one at the last position
    int posTemp = tryFuelPosition(lastPos, consume);
    if (posTemp > 0) {
      return posTemp;
    }
  }

  // find a new handler among our tanks
  for (BlockPos pos : tankSupplier.get()) {
    // already checked the last position above, no reason to try again
    if (!pos.equals(lastPos)) {
      int posTemp = tryFuelPosition(pos, consume);
      if (posTemp > 0) {
        return posTemp;
      }
    }
  }

  // no handler found, tell client of the lack of fuel
  if (consume) {
    temperature = 0;
    rate = 0;
  }
  return 0;
}

private int tryFuelPosition(BlockPos pos, boolean consume) {
  LazyOptional<IFluidHandler> tankCap = getTankHandlers().get(pos);
  if (tankCap != null && tankCap.isPresent()) {
    // if we find a valid cap, try to consume fuel from it
    int temperature = tryLiquidFuel(tankCap.orElse(EmptyFluidHandler.INSTANCE), consume);
    if (temperature > 0) {
      clearLastListener();
      fluidHandler = tankCap;
      tankCap.addListener(fluidListener);
      lastPos = pos;
      return temperature;
    }
  }
  return 0;
}

private Map<BlockPos,LazyOptional<IFluidHandler>> getTankHandlers() {
  if (tankHandlers == null) {
    tankHandlers = new LinkedHashMap<>();
    Level world = getLevel();
    for (BlockPos pos : tankSupplier.get()) {
      BlockEntity te = world.getBlockEntity(pos);
      if (te != null) {
        LazyOptional<IFluidHandler> handler = te.getCapability(ForgeCapabilities.FLUID_HANDLER);
        if (handler.isPresent()) {
          handler.addListener(tankHandlerListener);
          tankHandlers.put(pos, handler);
        }
      }
    }
  }
  return tankHandlers;
}

private void clearLastListener() {
  super.resetHandler(null);
}

@Override
public int fill(FluidStack resource, FluidAction action) {
  // if full or nothing being filled, do nothing
  if (contained >= capacity || resource.isEmpty()) {
    return 0;
  }

  // determine how much we can fill
  int usable = Math.min(capacity - contained, resource.getAmount());
  // could be negative if the smeltery size changes then you try filling it
  if (usable <= 0) {
    return 0;
  }

  // done here if just simulating
  if (action.simulate()) {
    return usable;
  }

  // add contained fluid amount
  contained += usable;

  // check if we already have the given liquid
  for (FluidStack fluid : fluids) {
    if (fluid.isFluidEqual(resource)) {
      // yup. add it
      fluid.grow(usable);
      parent.notifyFluidsChanged(FluidChange.CHANGED, fluid);
      // notify as we lost the "empty tank"
      if (contained >= capacity) {
        tankListChange.run();
      }
      return usable;
    }
  }

  // not present yet, add it
  resource = resource.copy();
  resource.setAmount(usable);
  fluids.add(resource);
  parent.notifyFluidsChanged(FluidChange.ADDED, resource);
  // notify as we added a new fluid
  tankListChange.run();
  return usable;
}

